<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\AdminRecord; use Illuminate\Http\RedirectResponse; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\View\View;
class RecordController extends Controller { private function admin(){abort_unless(auth()->user()?->hasRole('super-admin'),403);} public function index(string $module):View{$this->admin();$records=AdminRecord::where('module',$module)->when($module==='job-master-industries',fn($q)=>$q->orderByRaw("CAST(JSON_UNQUOTE(JSON_EXTRACT(payload, '$.sort_order')) AS UNSIGNED)")->orderBy('name'))->latest()->get();return view('admin.records.index',compact('module','records'));} public function create(string $module):View{$this->admin();return view('admin.records.form',['module'=>$module,'record'=>null]);} public function store(Request $request,string $module):RedirectResponse{$this->admin();AdminRecord::create($this->data($request,$module));return redirect()->route('admin.records.index',$module)->with('success','Record created.');} public function edit(string $module,AdminRecord $record):View{$this->admin();abort_unless($record->module===$module,404);return view('admin.records.form',compact('module','record'));} public function update(Request $request,string $module,AdminRecord $record):RedirectResponse{$this->admin();abort_unless($record->module===$module,404);$record->update($this->data($request,$module));return redirect()->route('admin.records.index',$module)->with('success','Record updated.');} public function destroy(string $module,AdminRecord $record):RedirectResponse{$this->admin();abort_unless($record->module===$module,404);$record->delete();return back()->with('success','Record deleted.');} private function data(Request $request,string $module):array{$data=$request->validate(['name'=>'required|string|max:150','description'=>'nullable|string','payload'=>'nullable|string','sort_order'=>'nullable|integer|min:0','icon_image'=>'nullable|image|max:2048']);$payload=filled($data['payload']??null)?json_decode($data['payload'],true):[];if($module==='job-master-industries'){ $payload['sort_order']=(int)($data['sort_order']??0);if($request->hasFile('icon_image')){$file=$request->file('icon_image');$directory=public_path('uploads/master-icons');if(!is_dir($directory))mkdir($directory,0755,true);$name='industry-'.now()->format('YmdHis').'-'.Str::random(6).'.'.$file->extension();$file->move($directory,$name);$payload['icon_image_url']=asset('uploads/master-icons/'.$name);}}return ['module'=>$module,'name'=>$data['name'],'slug'=>Str::slug($data['name']),'description'=>$data['description']??null,'payload'=>$payload,'is_active'=>$request->boolean('is_active')];} }